def run_checked (self):
        """Print periodic status messages."""
        if self.debug:
            self.logger.debug("starting thread run_checked")
        while not self.stopped:
            if self.debug:
                self.logger.debug("thread run_checked running")
            if self.paused:
                time.sleep(0.1)
                continue
            self.check_status()
            time.sleep(self.interval)
        if self.debug:
            self.logger.debug("thread run_checked stopping")

